test('when call .choices() then returns this', () => {
  const option = new Option('-e,--example <value>');
  const result = option.choices(['a']);
  assert.equal(result, option);
});

### 自定义选项处理

选项的参数可以通过自定义函数来处理，该函数接收两个参数，即用户新输入的参数值和当前已有的参数值（即上一次调用自定义处理函数后的返回值），返回新的选项参数值。

自定义函数适用场景包括参数类型转换，参数暂存，或者其他自定义处理的场景。

可以在自定义函数的后面设置选项参数的默认值或初始值（例如参数用列表暂存时需要设置一个初始空列表)。

示例代码：[options-custom-processing.js](./examples/options-custom-processing.js)

```js
function myParseInt(value, dummyPrevious) {
  // parseInt 参数为字符串和进制数
  const parsedValue = parseInt(value, 10);

choices(values) {
  this.argChoices = values.slice();
  this.parseArg = (arg, previous) => {
    if (!this.argChoices.includes(arg)) {
      throw new InvalidArgumentError(
        `Allowed choices are ${this.argChoices.join(', ')}.`,
      );
    }
    if (this.variadic) {
      return this._collectValue(arg, previous);
    }
    return arg;
  };
  return this;
}

test('when variadic used with choices and two values then set in array', () => {
  const program = new commander.Command();
  program.addOption(
    new commander.Option('-r,--required <value...>').choices([
      'one',
      'two',
    ]),
  );

  program.parse(['--required', 'one', 'two'], { from: 'user' });
  assert.deepEqual(program.opts().required, ['one', 'two']);
});

### 作为属性的遗留选项

在 Commander 7 以前，选项的值是作为属性存储在命令对象上的。
这种处理方式便于实现，但缺点在于，选项可能会与`Command`的已有属性相冲突。通过使用`.storeOptionsAsProperties()`，可以恢复到这种旧的处理方式，并可以不加改动地继续运行遗留代码。

```js
program
  .storeOptionsAsProperties()
  .option('-d, --debug')
  .action((commandAndOptions) => {
    if (commandAndOptions.debug) {
      console.error(`Called ${commandAndOptions.name()}`);
    }
  });
```

test('when variadic used with choices and two values then set in array', () => {
  const program = new commander.Command();
  let passedArg;
  program
    .addArgument(new commander.Argument('<value...>').choices(['one', 'two']))
    .action((value) => {
      passedArg = value;
    });

  program.parse(['one', 'two'], { from: 'user' });
  assert.deepEqual(passedArg, ['one', 'two']);
});

### 变长参数选项

定义选项时，可以通过使用`...`来设置参数为可变长参数。在命令行中，用户可以输入多个参数，解析后会以数组形式存储在对应属性字段中。在输入下一个选项前（`-`或`--`开头），用户输入的指令均会被视作变长参数。与普通参数一样的是，可以通过`--`标记当前命令的结束。

示例代码：[options-variadic.js](./examples/options-variadic.js)

```js
program
  .option('-n, --number <numbers...>', 'specify numbers')
  .option('-l, --letter [letters...]', 'specify letters');

program.parse();

console.log('Options: ', program.opts());
console.log('Remaining arguments: ', program.args);
```

test('when variadic used with choices and one value then set in array', () => {
  const program = new commander.Command();
  program.addOption(
    new commander.Option('-r,--required <value...>').choices([
      'one',
      'two',
    ]),
  );

  program.parse(['--required', 'one'], { from: 'user' });
  assert.deepEqual(program.opts().required, ['one']);
});

## .help() 与 .outputHelp() 的回调函数参数

这两个方法曾允许传入一个回调函数，以在展示前处理帮助信息。

```js
program.outputHelp((text) => {
  return colors.red(text);
});
```

新的写法是直接通过调用`.helpInformation()`来获取帮助文本。

```js
console.error(colors.red(program.helpInformation()));
```

自 Commander v7 起不再推荐使用。

